function materialText(key) { return materialCopy[language]?.[key] || materialCopy.uz[key]; }
function materialTypeText(type) { return materialText(type === "pdf" ? "pdf" : type === "video" ? "video" : type === "audio" ? "audio" : "text"); }
function renderLessonResource(lesson) {
  if (lesson.external_video_url) {
    let parsed;
    try { parsed = new URL(lesson.external_video_url); } catch { return ""; }
    const playlistId=parsed.searchParams.get("list");
    const videoId = parsed.hostname === "youtu.be" ? parsed.pathname.slice(1) : parsed.searchParams.get("v") || (parsed.pathname.startsWith("/playlist") ? null : parsed.pathname.split("/").filter(Boolean).pop());
    if (playlistId||videoId) {
      const params = new URLSearchParams({enablejsapi:"1",origin:location.origin,controls:"1",disablekb:"0",rel:"0",playsinline:"1",hl:language,cc_lang_pref:language});
      if (playlistId) params.set("list",playlistId);
      return `<div class="lesson-resource youtube-watch"><iframe data-watch-youtube="${escapeHtml(lesson.id)}" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(videoId||"videoseries")}?${params}" title="${escapeHtml(lesson.title)}" allow="accelerometer; encrypted-media; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin"></iframe></div>`;
    }
  }
  if (!lesson.resource_url || lesson.resource_type === "text") return "";
  const url=escapeHtml(lesson.resource_url);
  if (lesson.resource_type === "video") return `<div class="lesson-resource"><video controls preload="metadata" controlsList="nodownload noplaybackrate" disablePictureInPicture data-watch-video="${escapeHtml(lesson.id)}" src="${url}"></video></div>`;
  if (lesson.resource_type === "audio") return `<div class="lesson-resource"><audio controls preload="metadata" src="${url}"></audio></div>`;
  if (lesson.resource_type === "pdf") return `<div class="lesson-resource"><a class="button button-outline button-small" href="${url}" target="_blank" rel="noopener">${escapeHtml(materialText("openPdf"))} ↗</a></div>`;
  return "";
}
function setupVideoCompletion(container, courseId, lesson) {
  const video = container.querySelector(`[data-watch-video="${lesson.id}"]`);
  const youtubeFrame = container.querySelector(`[data-watch-youtube="${lesson.id}"]`);
  if (!video && !youtubeFrame) return;
  const button = document.querySelector(`[data-complete="${lesson.id}"]`);
  const meter = document.querySelector(`[data-watch-progress="${lesson.id}"]`);
  let furthest = 0, lastReport = 0, busy = false;
  const updateMeter = (result) => {
    if (meter) meter.textContent = `${Math.floor(result.completion_percent)}% · ${videoWatchCopy[language]}`;
    if (result.can_complete && button) { button.disabled=false; button.textContent=t("markComplete"); }
  };
  const report = async (position, duration, itemIndex=0, itemCount=1, force=false, ended=false, playbackRate=video?.playbackRate||1) => {
    if (busy || (!force && Math.abs(position-lastReport) < 4.5)) return;
    busy=true; lastReport=position;
    try {
      const result=await api(`/courses/${courseId}/progress/lessons/${lesson.id}/video-watch`, {
        method:"POST",body:JSON.stringify({position_seconds:position,duration_seconds:duration,item_index:itemIndex,item_count:itemCount,playback_rate:playbackRate,ended})
      });
      updateMeter(result);
    } catch {} finally {busy=false;}
  };
  const progressReady = api(`/courses/${courseId}/progress/lessons/${lesson.id}/video-watch`).then(result=>{
    furthest=result.furthest_position_seconds;
    updateMeter(result);
    return result;
  }).catch(()=>null);
  if(video){
    video.playbackRate=1;
    const initializeVideo = async () => {
      await progressReady;
      if (furthest > 0 && furthest < video.duration) video.currentTime=furthest;
      report(furthest,video.duration,0,1,true);
    };
    if(video.readyState>=1) initializeVideo();
    else video.addEventListener("loadedmetadata",initializeVideo,{once:true});
    video.addEventListener("ratechange",()=>{if(video.playbackRate!==1)video.playbackRate=1;});
    video.addEventListener("seeking",()=>{if(video.currentTime>furthest+1.5)video.currentTime=furthest;});
    video.addEventListener("timeupdate",()=>{
      if(video.currentTime<=furthest+1.5)furthest=Math.max(furthest,video.currentTime);
      report(furthest,video.duration,0,1);
    });
    video.addEventListener("ended",()=>{furthest=video.duration;report(furthest,video.duration,0,1,true,true);});
    return;
  }
  loadYouTubeIframeApi().then(()=>progressReady).then(()=>new Promise((resolve,reject)=>{
    let player,activeIndex=0,itemCount=1,activeDuration=0,timer;
    const loadItemProgress = async (index,count) => {
      const result=await api(`/courses/${courseId}/progress/lessons/${lesson.id}/video-watch?item_index=${index}`);
      furthest=result.furthest_position_seconds;
      lastReport=furthest;
      updateMeter(result);
      return result;
    };
    const poll = async () => {
      if(!player||busy)return;
      const playlist=player.getPlaylist()||[];
      const nextCount=Math.max(1,playlist.length);
      const nextIndex=Math.max(0,player.getPlaylistIndex()||0);
      if(nextIndex!==activeIndex||nextCount!==itemCount){
        if(activeDuration>0) await report(player.getCurrentTime()||furthest,activeDuration,activeIndex,itemCount,true,false,player.getPlaybackRate()||1);
        activeIndex=nextIndex;itemCount=nextCount;activeDuration=player.getDuration()||0;
        await loadItemProgress(activeIndex,itemCount);
        return;
      }
      const duration=player.getDuration()||activeDuration;
      const position=player.getCurrentTime()||0;
      if(duration>0)activeDuration=duration;
      if(player.getPlayerState()===1){
        furthest=Math.max(furthest,position);await report(position,duration,activeIndex,itemCount,false,false,player.getPlaybackRate()||1);
      } else if(player.getPlayerState()===0&&duration>0){
        furthest=duration;
        await report(furthest,duration,activeIndex,itemCount,true,true,player.getPlaybackRate()||1);
      }
    };
    player=new YT.Player(youtubeFrame,{events:{
      onReady:async(event)=>{
        player=event.target;
        try {
          itemCount=Math.max(1,(player.getPlaylist()||[]).length);
          activeIndex=Math.max(0,player.getPlaylistIndex()||0);
          activeDuration=player.getDuration()||0;
          await loadItemProgress(activeIndex,itemCount);
          timer=window.setInterval(poll,1000);
        } catch { if(meter)meter.textContent=videoWatchCopy[language]; }
        resolve();
      },
      onStateChange:(event)=>{if(event.data===0&&activeDuration>0){furthest=activeDuration;report(activeDuration,activeDuration,activeIndex,itemCount,true,true,player.getPlaybackRate()||1);}},
      onError:()=>{if(meter)meter.textContent=videoWatchCopy[language];}
    }});
    const cleanupObserver=new MutationObserver(()=>{
      if(!container.isConnected||!container.contains(youtubeFrame)){
        window.clearInterval(timer);
        player?.destroy?.();
        cleanupObserver.disconnect();
      }
    });
    cleanupObserver.observe(container.closest("#enrolledCourses")||document.body,{childList:true,subtree:true});
  })).catch(()=>{if(meter)meter.textContent=videoWatchCopy[language];});
}
