function t(key) { return quizUiCopy[language]?.[key] || featureCopy[language]?.[key] || dashboardCopy[language]?.[key] || copy[language]?.[key] || copy.uz[key] || key; }
function shuffled(items) {
  const result = [...items];
  for (let index = result.length - 1; index > 0; index--) {
    const swap = Math.floor(Math.random() * (index + 1));
    [result[index], result[swap]] = [result[swap], result[index]];
  }
  return result;
}
function shuffledQuestion(question) {
  const choiceOrder = shuffled(question.choices.map((_, index) => index));
  return { ...question, choiceOrder, choices: choiceOrder.map((index) => question.choices[index]) };
}
