function addResourceControls(container,cards) {
  const lessonsById=new Map(cards.flatMap(({lessonData})=>lessonData.map(({lesson})=>[lesson.id,lesson])));
  const accepted={text:"",pdf:"application/pdf",video:"video/mp4,video/webm",audio:"audio/mpeg,audio/mp4,audio/wav,audio/ogg,audio/webm"};
  for (const form of container.querySelectorAll("[data-lesson-course], [data-lesson-edit]")) {
    const isEdit=form.hasAttribute("data-lesson-edit");
    const lesson=isEdit?lessonsById.get(form.dataset.lessonId):null;
    const currentType=lesson?.resource_type || "text";
    if (isEdit && lesson) {
      const badge=document.createElement("small");
      badge.className="lesson-material-badge";
      badge.textContent=materialTypeText(currentType);
      form.closest(".owned-lesson")?.querySelector(".owned-lesson-head b")?.after(badge);
    }
    const fieldset=document.createElement("div");
    fieldset.className="resource-picker";
    const typeLabel=document.createElement("label");
    const typeCaption=document.createElement("span");
    typeCaption.textContent=materialText("type");
    const select=document.createElement("select");
    select.name="resource_type";
    select.innerHTML=[["text",materialText("text")],["pdf",materialText("pdf")],["video",materialText("video")],["audio",materialText("audio")]].map(([value,label])=>`<option value="${value}">${escapeHtml(label)}</option>`).join("");
    select.value=currentType;
    typeLabel.append(typeCaption,select);
    const fileLabel=document.createElement("label");
    const fileCaption=document.createElement("span");
    fileCaption.textContent=materialText("file");
    const input=document.createElement("input");
    input.type="file";
    input.name="resource_file";
    input.accept=accepted[currentType];
    fileLabel.append(fileCaption,input);
    const videoLinkLabel=document.createElement("label");
    const videoLinkCaption=document.createElement("span");
    videoLinkCaption.textContent=({uz:"YouTube video havolasi (ixtiyoriy)",en:"YouTube video link (optional)",ru:"Ссылка на видео YouTube (необязательно)",ko:"YouTube 동영상 링크 (선택 사항)"})[language];
    const videoLink=document.createElement("input");
    videoLink.type="url";videoLink.name="external_video_url";videoLink.placeholder="https://youtu.be/...";videoLink.value=lesson?.external_video_url||"";
    videoLinkLabel.append(videoLinkCaption,videoLink);
    const hint=document.createElement("small");
    hint.textContent=materialText("hint");
    fieldset.append(typeLabel,fileLabel,videoLinkLabel,hint);
    videoLinkLabel.hidden=select.value!=="video";
    if(isEdit && lesson?.resource_key){
      const removeButton=document.createElement("button");
      removeButton.type="button";
      removeButton.className="button button-outline button-small resource-remove";
      removeButton.textContent=materialText("removeResource");
      removeButton.addEventListener("click",async()=>{
        removeButton.disabled=true;
        try{await api(`/courses/${form.dataset.lessonEdit}/lessons/${form.dataset.lessonId}/resource`,{method:"DELETE"});await loadInstructorCourses();}
        catch(error){removeButton.disabled=false;alert(error.message||t("studioError"));}
      });
      fieldset.append(removeButton);
    }
    const message=form.querySelector(".studio-form-message");
    const insertionPoint=form.querySelector(".studio-form-actions") || form.querySelector("button[type=submit],button:not([type])") || message;
    form.insertBefore(fieldset,insertionPoint);
    select.addEventListener("change",()=>{input.accept=accepted[select.value];videoLinkLabel.hidden=select.value!=="video";input.required=false;});
    input.required=false;
  }
}

async function uploadLessonResource(courseId,lessonId,file) {
  try {
    await api(`/courses/${courseId}/lessons/${lessonId}/resource`,{
      method:"PUT",body:file,headers:{"Content-Type":file.type || "application/octet-stream"}
    });
  } catch (error) {
    if (error.status === 415 || error.status === 413) throw new Error(`${materialText("uploadFailed")} ${error.message}`);
    throw error;
  }
}

